from __future__ import annotations
import math
from collections import defaultdict
from pydantic import BaseModel,ConfigDict,Field
from cbim_sdk import CBIMProject
from cbim_sdk.models import Beam,Column,Door,Equipment,Fitting,Opening,Pipe,Slab,Space,Wall,Window

class QuantityModel(BaseModel): model_config=ConfigDict(extra='forbid')
class QuantityRow(QuantityModel):
    element_id:str; type:str; storey_id:str|None=None; system_id:str|None=None; manufacturer:str|None=None; line:str|None=None
    length_m:float=0; area_m2:float=0; volume_m3:float=0; count:float=1
class QuantitySummary(QuantityModel):
    rows:list[QuantityRow]=Field(default_factory=list); totals_by_type:dict[str,dict[str,float]]=Field(default_factory=dict); totals_by_system:dict[str,dict[str,float]]=Field(default_factory=dict)

def _poly_area(points):
    xy=[(p.x,p.y) for p in points];return abs(sum(x1*y2-x2*y1 for (x1,y1),(x2,y2) in zip(xy,xy[1:]+xy[:1])))/2 if len(xy)>=3 else 0

class QuantityCalculator:
    def calculate(self,project:CBIMProject)->QuantitySummary:
        rows=[]
        for e in project.elements:
            row=QuantityRow(element_id=e.id,type=e.type,storey_id=e.storey_id,system_id=getattr(e,'system_id',None),manufacturer=e.properties.get('catalog_manufacturer'),line=e.properties.get('catalog_line'))
            if isinstance(e,Wall): row.length_m=e.length;row.area_m2=e.length*e.height;row.volume_m3=row.area_m2*e.thickness
            elif isinstance(e,Column): row.volume_m3=e.width*e.depth*e.height
            elif isinstance(e,Beam): row.length_m=math.dist((e.start.x,e.start.y,e.start.z),(e.end.x,e.end.y,e.end.z));row.volume_m3=row.length_m*e.width*e.height
            elif isinstance(e,Slab): row.area_m2=_poly_area(e.boundary);row.volume_m3=row.area_m2*e.thickness
            elif isinstance(e,Space): row.area_m2=_poly_area(e.boundary);row.volume_m3=row.area_m2*e.height
            elif isinstance(e,Pipe): row.length_m=sum(math.dist((a.x,a.y,a.z),(b.x,b.y,b.z)) for a,b in zip(e.path,e.path[1:]));row.volume_m3=math.pi*(e.diameter/2)**2*row.length_m
            elif isinstance(e,(Door,Window)): row.area_m2=e.width*e.height
            elif isinstance(e,Opening): row.area_m2=e.width*e.height;row.volume_m3=row.area_m2*(e.depth or 0)
            elif isinstance(e,(Fitting,Equipment)): pass
            rows.append(row)
        def aggregate(keyfn):
            acc=defaultdict(lambda:defaultdict(float))
            for r in rows:
                k=keyfn(r)
                if not k:continue
                for q in ('length_m','area_m2','volume_m3','count'): acc[k][q]+=getattr(r,q)
            return {k:{q:round(v,6) for q,v in vals.items()} for k,vals in sorted(acc.items())}
        return QuantitySummary(rows=rows,totals_by_type=aggregate(lambda r:r.type),totals_by_system=aggregate(lambda r:r.system_id))
